CREATE OR REPLACE FUNCTION ECAMS.SYSPCCHECK
(ACPTNO IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT1 INT := 0;
 --- 빌드준비작업단계가 있는지 CHECK
BEGIN
    SELECT  COUNT(*)
      INTO  VCNT1
      FROM  CMR9900 A
     WHERE  A.CR_ACPTNO=ACPTNO
       AND  A.CR_TEAMCD='1'
       AND  A.CR_LOCAT<>'00'
       AND  A.CR_STATUS='9'
       AND  A.CR_TEAM='SYSPC';

     IF VCNT1 > 0 THEN
        RETURN 'Y';
     END IF;

    SELECT  COUNT(*)
      INTO  VCNT1
      FROM  CMR9900 A
     WHERE  A.CR_ACPTNO=ACPTNO
       AND  A.CR_TEAMCD='1'
       AND  A.CR_LOCAT<>'00'
       AND  A.CR_STATUS='3'
       AND  A.CR_CONFDATE IS NOT NULL
       AND  A.CR_TEAM='SYSPC';

     IF VCNT1 > 0 THEN
        RETURN 'Y';
     ELSE
        RETURN 'N';
     END IF;
end;